<script setup>
import {reactive,ref} from 'vue'
import {authRequest,notify,state} from '../lib/state'
const busy=ref(false),sent=ref(false),form=reactive({rating:5,area:'general',comment:''})
async function send(){try{busy.value=true;await authRequest('/feedback',{method:'POST',body:form});sent.value=true;notify('¡Gracias por ayudarnos a mejorar Hobbiz!')}catch(e){notify(e.message)}finally{busy.value=false}}
</script>
<template><div class="page"><div class="page-heading"><div><div class="eyebrow earth">VALIDACIÓN DEL PROTOTIPO</div><h1>Cuéntanos tu experiencia</h1><p class="muted">Tu opinión ayudará al equipo universitario a validar Hobbiz.</p></div></div><section class="form-card" style="max-width:750px"><div v-if="sent" class="empty"><h2>¡Gracias por participar!</h2><p>Tu respuesta quedó registrada {{state.mode==='demo'?'en esta sesión de demostración':'para su evaluación'}}.</p></div><form v-else class="form-grid" @submit.prevent="send"><label>¿Qué parte evaluaste?<select v-model="form.area"><option value="general">Uso general</option><option value="busqueda">Búsqueda y filtros</option><option value="reserva">Reserva</option><option value="tallerista">Panel de tallerista</option></select></label><label>Calificación (1-5)<select v-model.number="form.rating"><option v-for="s in 5" :key="s" :value="s">{{s}} estrellas</option></select></label><label class="span-all">¿Qué mejorarías?<textarea v-model.trim="form.comment" minlength="10" maxlength="1000" required rows="5" placeholder="Cuéntanos qué fue claro, qué resultó difícil y qué agregarías..."/></label><p class="small muted span-all">No ingreses datos personales sensibles.</p><button class="btn primary" :disabled="busy">Enviar opinión</button></form></section></div></template>
